"""Conditional abstract-address provenance; never execute the embedded DLL.

Fixture: exact two raw High P-Code functions and 3072-byte /Od target from the
Apache-2.0 Ghidra deobExample.c campaign, retained solely for static admission.
Upstream: NationalSecurityAgency/ghidra at8b6bbb857accdfa20dc5b2f5dea471178c2e9fbc
GhidraDocs/GhidraClass/ExerciseFiles/Emulation/Source/deobExample.c
"""
import base64,copy,hashlib,json,zlib,dataclasses
from pathlib import Path
import pytest
from aether_re.call_closure import reconstruct_direct_call_closure
from aether_re.ghidra_headless_bridge import GhidraFunctionInfo,GhidraDecompilationResult

RAW_BLOB=''
DLL_BLOB=''
RAW=json.loads(zlib.decompress(base64.b64decode(RAW_BLOB)))
MODEL='bounded-direct-effects-calls.v1'
def external_export(tmp_path):
    data=copy.deepcopy(RAW);binary=tmp_path/'unexecuted-external-Od.dll'
    binary.write_bytes(base64.b64decode(DLL_BLOB))
    assert hashlib.sha256(binary.read_bytes()).hexdigest()==data['target_sha256']
    fields={f.name for f in dataclasses.fields(GhidraFunctionInfo) if f.init}
    functions={k:GhidraFunctionInfo(**{n:v for n,v in item.items() if n in fields}) for k,item in data['functions'].items()}
    return GhidraDecompilationResult(str(binary),True,2,2,functions,'','',0,target_sha256=data['target_sha256'],status='complete')

@pytest.mark.parametrize('name',['length','deobfuscate'])
def test_real_pointer_phi_values_can_live_in_private_stack_ssa(tmp_path,name):
    report=reconstruct_direct_call_closure(external_export(tmp_path),name,call_model=MODEL)
    assert report['status']=='complete',report
    member=next(f for f in report['call_model']['functions'] if f['label']==name)
    proof=member['pointer_provenance_proof']
    assert proof['status']=='conditional_address_derivation'
    assert proof['original_ram_pointer_proved'] is proof['abi_recovered'] is proof['binary_equivalence_proved'] is False
    assert proof['ir_payload_sha256']==member['payload_sha256']
    assert len(proof['used_address_formals'])==(1 if name=='length' else 2)
    assert any('three runtime statuses' in h for h in report['call_model']['hypotheses'])
    assert any('observed pointer formals conditionally' in h for h in report['call_model']['hypotheses'])

def data_and_roots():
    f=next(f for f in RAW['functions'].values() if f['name']=='length')
    return copy.deepcopy(f['pcode_ir']),{'v221'}

def solver(data,roots,**kwargs):
    from aether_re.pointer_provenance import prove_pointer_provenance
    return prove_pointer_provenance(data,roots,observation_sha256='a'*64,**kwargs)

@pytest.mark.parametrize('mutation,reason',[
 ('stack_input','stack_input'),('mixed_phi','unknown'),('constant','unknown'),
 ('integer_add','definition'),('loaded','definition'),('missing_formal','input')])
def test_frame_unknown_and_mixed_phi_addresses_fail_closed(mutation,reason):
    data,roots=data_and_roots();vs={v['id']:v for v in data['varnodes']};ops={o['id']:o for o in data['operations']}
    if mutation=='stack_input':vs['v221'].update(kind='stack',space='stack',offset='8')
    if mutation=='mixed_phi':ops['o3']['inputs'][0]='v219'
    if mutation=='constant':ops['o1']['inputs']=['v219']
    if mutation=='integer_add':ops['o5'].update(opcode='INT_ADD',inputs=['v373','v75'])
    if mutation=='loaded':ops['o1'].update(opcode='LOAD',inputs=['v389','v221'])
    if mutation=='missing_formal':roots=set()
    with pytest.raises(ValueError,match=reason):solver(data,roots)

def test_a_formal_arm_cannot_legitimize_another_closed_phi_component():
    data,roots=data_and_roots();ops={o['id']:o for o in data['operations']}
    # Graph counterexample: original anchored phi now also reaches a separate
    # closed COPY cycle. Structural SSA checking remains a separate prerequisite.
    data['varnodes'].extend([dict(id='bad1',size=8,kind='unique',input=False,definition='badop1'),dict(id='bad2',size=8,kind='unique',input=False,definition='badop2')])
    data['operations'].extend([dict(id='badop1',opcode='COPY',inputs=['bad2'],output='bad1'),dict(id='badop2',opcode='COPY',inputs=['bad1'],output='bad2')])
    ops['o3']['inputs'][1]='bad1'
    with pytest.raises(ValueError,match='unseeded'):solver(data,roots)

def test_pointer_sub_constant_field_offset_retains_the_declared_root():
    data,roots=data_and_roots();op=next(o for o in data['operations'] if o['id']=='o5')
    op.update(opcode='PTRSUB',inputs=['v373','v75'])
    proof=solver(data,roots)
    assert proof['used_address_formals']==['v221']

def test_pointer_budget_exhaustion_is_a_refusal():
    data,roots=data_and_roots()
    with pytest.raises(ValueError,match='budget'):solver(data,roots,max_visits=1)

def test_pure_stack_address_guard_is_preserved(tmp_path):
    export=external_export(tmp_path);data=copy.deepcopy(export.get_unique_function('length').pcode_ir)
    from aether_re.call_closure import _stack_ssa,_Refused
    with pytest.raises(_Refused,match='stack_address_unmodeled'):_stack_ssa(data)

def caller_of_pointer_leaf(tmp_path,*,constant_argument=False,unknown_argument=False):
    export=external_export(tmp_path);leaf=export.get_unique_function('length')
    data=copy.deepcopy(leaf.pcode_ir);vs={v['id']:v for v in data['varnodes']}
    pc='ram:180001050';data['function_address']=pc
    data['varnodes']=[vs[i] for i in ('v221','v219','v220')]
    vs['v220']['definition']='o0'
    data['varnodes'].append(dict(id='target',space='ram',kind='memory',offset='180001000',size=8,input=False,free=True,persistent=False,unaffected=False,addr_tied=False))
    data['operations']=[dict(id='o0',opcode='CALL',inputs=['target','v219' if constant_argument else 'v221'],output='v220',sequence=dict(pc=pc,time=0,order=0)),dict(id='o1',opcode='RETURN',inputs=['v219','v220'],sequence=dict(pc=pc,time=1,order=1))]
    data['entry_block']='b0';data['blocks']=[dict(id='b0',start=pc,stop='ram:180001058',predecessors=[],successors=[],operations=['o0','o1'])]
    high=copy.deepcopy(leaf.high_parameter_observation);high['function_address']=pc
    if unknown_argument:high['parameters'][0]['type_name']='unsigned long long'
    from aether_re.ghidra_pcode_ir import analyze_high_pcode
    analysis=analyze_high_pcode(data,expected_target=export.target_sha256,expected_address=pc,evidence_sha256='b'*64)
    caller=GhidraFunctionInfo('wrapper',pc,True,1,'int',function_id=export.target_sha256+'!'+pc,pcode_ir=data,ir_analysis=analysis['summary'],normalized_ir=analysis['graph'],high_parameter_observation=high)
    export.functions={leaf.function_id:leaf,caller.function_id:caller}
    return export

def test_callee_address_requirements_are_proved_at_the_caller(tmp_path):
    report=reconstruct_direct_call_closure(caller_of_pointer_leaf(tmp_path),'wrapper',call_model=MODEL)
    assert report['status']=='complete',report
    assert all('pointer_provenance_proof' in f for f in report['call_model']['functions'])

@pytest.mark.parametrize('kind',['constant_argument','unknown_argument'])
def test_callee_declared_pointer_does_not_authorize_unknown_caller_argument(tmp_path,kind):
    report=reconstruct_direct_call_closure(caller_of_pointer_leaf(tmp_path,**{kind:True}),'wrapper',call_model=MODEL)
    assert report['status']=='unsupported',report
    assert 'pointer_provenance_unknown' in report['errors'][0],report

def test_pointer_observation_and_proof_bind_the_context_fingerprint(tmp_path):
    export=external_export(tmp_path)
    original=reconstruct_direct_call_closure(export,'length',call_model=MODEL)
    leaf=export.get_unique_function('length');high=copy.deepcopy(leaf.high_parameter_observation)
    high['parameters'][0]['type_name']='unsigned char *'
    changed=dataclasses.replace(leaf,high_parameter_observation=high)
    export.functions[leaf.function_id]=changed
    new=reconstruct_direct_call_closure(export,'length',call_model=MODEL)
    assert original['status']==new['status']=='complete'
    assert original['call_model']['context_sha256']!=new['call_model']['context_sha256']
    oldproof=original['call_model']['functions'][0]['pointer_provenance_proof']
    newproof=new['call_model']['functions'][0]['pointer_provenance_proof']
    assert oldproof['observation_sha256']!=newproof['observation_sha256']
